            role: "owner" | "admin" | "editor" | "viewer";
            /** @description Suspended by Ladoo: it can't be opened until support lifts it */
            suspended: boolean;
            /**
             * @description `inherited`: no membership here, but owner/admin of an agency above it
             * @enum {string}
             */
            access: "member" | "inherited";
            /** @description Whether you get this workspace's morning summary email (null with inherited access). */
            daily_digest: boolean | null;
